package local.tvmorph.tv;
import org.json.*;import com.sun.net.httpserver.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class XtreamMetadataCheck{
 public static void main(String[] args)throws Exception{HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);AtomicInteger calls=new AtomicInteger(),bad=new AtomicInteger();ExecutorService requests=Executors.newFixedThreadPool(2);
 server.createContext("/player_api.php",exchange->{String q=exchange.getRequestURI().getRawQuery();calls.incrementAndGet();boolean fail=q.contains("series_id=8")&&bad.incrementAndGet()==1;try{Thread.sleep(100);}catch(Exception ignored){}byte[] data="{\"info\":{\"plot\":\"Fixture\"},\"episodes\":{\"1\":[{\"id\":\"71\",\"title\":\"Episode\",\"container_extension\":\"mp4\"}]}}".getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(fail?503:200,data.length);exchange.getResponseBody().write(data);exchange.close();});server.start();
 try{String base="http://127.0.0.1:"+server.getAddress().getPort();Xtream x=new Xtream(new JSONObject().put("server",base).put("username","fixture").put("password","fixture"));JSONObject item=new JSONObject().put("kind","series").put("id","7");Future<?> a=requests.submit(()->{try{x.details(item);}catch(Exception e){throw new RuntimeException(e);}}),b=requests.submit(()->{try{x.episodes("7");}catch(Exception e){throw new RuntimeException(e);}});a.get();b.get();if(calls.get()!=1)throw new AssertionError("Duplicate concurrent series metadata: "+calls.get());x.episodes("7");if(calls.get()!=1)throw new AssertionError("Cache miss");x.clearMetadata();x.episodes("7");if(calls.get()!=2)throw new AssertionError("Refresh did not invalidate");boolean failed=false;try{x.episodes("8");}catch(Exception e){failed=true;}if(!failed)throw new AssertionError();x.episodes("8");if(calls.get()!=4)throw new AssertionError("Failure cached");System.out.println("PASS: native concurrent series details/episodes share one HTTP request; repeat cache, refresh invalidation and failed-request retry.");}finally{requests.shutdownNow();server.stop(0);}}
}
